\section{Introduction}

Teichm\"uller theory studies the space of complex structures on a fixed topological surface. In
genus one the entire theory becomes explicit, and this explicitness is a laboratory rather than
a degeneration: every deep phenomenon of the higher-genus theory --- the extremal quasiconformal
map, the Teichm\"uller metric, the orbifold structure of moduli space, the thick--thin
decomposition, Bers' formula for pseudo-Anosov translation lengths, Mumford compactness --- has
a genus-one shadow computable in closed form. We develop that shadow completely, never appealing
to the general theory.

Throughout $\HH=\{z\in\CC:\Imm z>0\}$ carries the hyperbolic metric of curvature $-1$, with
distance $\dH$ satisfying
\[
  \cosh \dH(z,w) \;=\; 1+\frac{|z-w|^2}{2\,\Imm z\,\Imm w}.
\]
We write $\rho=-\tfrac12+\tfrac{\sqrt3}{2}i$ for the hexagonal point and $i$ for the square
point, and $\varphi=(1+\sqrt5)/2$ for the golden ratio.

\section{The dilatation of a real-linear map}

\subsection{Normal form}
Every $\RR$-linear map $f:\CC\to\CC$ has a unique expression
\[
  f(z)=az+b\bar z,\qquad a,b\in\CC,
\]
with Jacobian determinant $J(f)=|a|^2-|b|^2$. We work throughout with the orientation-preserving
nonsingular maps, i.e.\ those with $|b|<|a|$, and write $\mathcal{L}$ for this set. The image of
the unit circle under $f$ is an ellipse with semi-axes $|a|+|b|$ and $|a|-|b|$.

\begin{definition}
For $f=(a,b)\in\mathcal{L}$ set
$K(f)=\dfrac{|a|+|b|}{|a|-|b|}$ (the \emph{dilatation}) and $\mu(f)=b/a$ (the \emph{Beltrami
coefficient}).
\end{definition}

\begin{proposition}\label{prop:basic}
For $f\in\mathcal{L}$: $J(f)>0$; $K(f)\ge1$; $K(f)=1$ if and only if $b=0$, in which case
$f(z)=az$ is conformal; $|\mu(f)|<1$; and $K(f)=\dfrac{1+|\mu(f)|}{1-|\mu(f)|}$.
\end{proposition}

\begin{proof}
Positivity of $J$ and of $|a|\pm|b|$ follows from $0\le|b|<|a|$; then $K\ge1$ is equivalent to
$|b|\ge0$, with equality iff $|b|=0$. Dividing numerator and denominator by $|a|>0$ gives the
Beltrami formula.
\end{proof}

\begin{lemma}[Determinant form]\label{lem:detform}
$K(f)=\dfrac{(|a|+|b|)^2}{J(f)}$.
\end{lemma}

\begin{proof}
$J(f)=(|a|+|b|)(|a|-|b|)$.
\end{proof}

\subsection{Composition}

\begin{definition}
For $f=(a,b)$ and $g=(c,d)$ set $f\circ g=(A,B)$ with $A=ac+b\bar d$, $B=ad+b\bar c$.
\end{definition}

\begin{proposition}
$(f\circ g)(z)=f(g(z))$ for all $z$, and $f\circ g\in\mathcal{L}$ if $f,g\in\mathcal{L}$.
\end{proposition}

\begin{proof}
$f(g(z))=a(cz+d\bar z)+b\overline{(cz+d\bar z)}=(ac+b\bar d)z+(ad+b\bar c)\bar z$; membership
follows from Theorem~\ref{thm:jacmult}, which gives $|A|^2-|B|^2=J(f)J(g)>0$.
\end{proof}

\begin{theorem}[Multiplicativity of the Jacobian]\label{thm:jacmult}
$|A|^2-|B|^2=\bigl(|a|^2-|b|^2\bigr)\bigl(|c|^2-|d|^2\bigr)$.
\end{theorem}

\begin{proof}
Expanding, $|A|^2=|ac|^2+|b\bar d|^2+2\Ree(ac\,\overline{b\bar d})$ and
$|B|^2=|ad|^2+|b\bar c|^2+2\Ree(ad\,\overline{b\bar c})$. The two cross terms are both
$2\Ree(a\bar b\,c d)$ and cancel; the remaining terms are
$|a|^2|c|^2+|b|^2|d|^2-|a|^2|d|^2-|b|^2|c|^2=(|a|^2-|b|^2)(|c|^2-|d|^2)$.
\end{proof}

\begin{theorem}[Submultiplicativity]\label{thm:submult}
For $f,g\in\mathcal{L}$, $K(f\circ g)\le K(f)K(g)$.
\end{theorem}

\begin{proof}
The triangle inequality gives $|A|\le|a||c|+|b||d|$ and $|B|\le|a||d|+|b||c|$, hence
$|A|+|B|\le(|a|+|b|)(|c|+|d|)$. By Lemma~\ref{lem:detform} and Theorem~\ref{thm:jacmult},
\[
  K(f\circ g)=\frac{(|A|+|B|)^2}{J(f)J(g)}
  \le\frac{(|a|+|b|)^2(|c|+|d|)^2}{J(f)J(g)}=K(f)K(g). \qedhere
\]
\end{proof}

\begin{remark}
The naive route fails: bounding the minor axis from below by the triangle inequality yields only
$|A|-|B|\ge(|a|-|b|)(|c|-|d|)-2|b||d|$, losing exactly the term $2|b||d|$. The repair is to bound
the \emph{product} $(|A|-|B|)(|A|+|B|)$ exactly, which is Theorem~\ref{thm:jacmult}; the
minor-axis inequality $|A|-|B|\ge(|a|-|b|)(|c|-|d|)$ is then a consequence rather than an input.
Submultiplicativity is an algebraic identity in disguise, not an analytic estimate.
\end{remark}

\begin{proposition}\label{prop:inv}
For $f=(a,b)\in\mathcal{L}$ the inverse is $f^{-1}=(\bar a/J(f),\,-b/J(f))\in\mathcal{L}$, and
$K(f^{-1})=K(f)$. Every $f\in\mathcal{L}$ is injective.
\end{proposition}

\begin{proof}
A computation using $J(f)=a\bar a-b\bar b$ shows $f(f^{-1}(z))=z$. Both $|a|$ and $|b|$ are
divided by $J$, so $K$ is unchanged. If $f(z)=0$ with $z\ne0$ then $|a||z|=|b||z|$, contradicting
$|b|<|a|$.
\end{proof}

\section{Teichm\"uller space of the torus}

A \emph{marked flat torus} is $\CC/\Lambda_\tau$ with $\Lambda_\tau=\ZZ+\ZZ\tau$, $\tau\in\HH$,
together with the ordered basis $(1,\tau)$. Marked tori are compared by plane maps sending
$1\mapsto1$ and $\tau\mapsto\tau'$.

\begin{lemma}[Reflection identity]\label{lem:refl}
For $\tau,\tau'\in\HH$,
$|\tau'-\bar\tau|^2=|\tau'-\tau|^2+4\Imm\tau\Imm\tau'$; in particular
$|\tau'-\tau|<|\tau'-\bar\tau|$.
\end{lemma}

\begin{proof}
With $\tau=x+iy$, $\tau'=x'+iy'$, both sides equal $(x'-x)^2+(y'+y)^2$.
\end{proof}

\begin{theorem}[Existence, uniqueness, extremality]\label{thm:affine}
There is exactly one $f\in\mathcal{L}$ with $f(1)=1$ and $f(\tau)=\tau'$, namely
\[
  \aff(\tau,\tau')=\left(\frac{\tau'-\bar\tau}{\tau-\bar\tau},\ \frac{\tau-\tau'}{\tau-\bar\tau}\right),
\]
so it is the minimal-dilatation marked map, with
\[
  K(\tau,\tau')=\frac{\bigl(|\tau'-\bar\tau|+|\tau'-\tau|\bigr)^2}{4\Imm\tau\Imm\tau'}.
\]
\end{theorem}

\begin{proof}
The marking conditions are the linear system $a+b=1$, $a\tau+b\bar\tau=\tau'$ with determinant
$\bar\tau-\tau\ne0$; solving gives the stated coefficients, and admissibility $|b|<|a|$ is
Lemma~\ref{lem:refl}. Uniqueness makes extremality automatic. Since
$|\tau-\bar\tau|=2\Imm\tau$ we get $|a|=|\tau'-\bar\tau|/(2\Imm\tau)$,
$|b|=|\tau'-\tau|/(2\Imm\tau)$, and Lemma~\ref{lem:refl} gives $J=\Imm\tau'/\Imm\tau$;
Lemma~\ref{lem:detform} concludes.
\end{proof}

\begin{proposition}[Groupoid property]\label{prop:groupoid}
$\aff(\tau',\tau'')\circ\aff(\tau,\tau')=\aff(\tau,\tau'')$ and
$\aff(\tau,\tau')^{-1}=\aff(\tau',\tau)$.
\end{proposition}

\begin{proof}
Each side is a marked map between the same pair, hence equal by uniqueness.
\end{proof}

\begin{definition}
$\dT(\tau,\tau')=\tfrac12\log K(\tau,\tau')$.
\end{definition}

\begin{theorem}\label{thm:metric}
$\dT$ is a metric on $\HH$.
\end{theorem}

\begin{proof}
Nonnegativity is $K\ge1$; vanishing forces $b=0$ in the affine map, i.e.\ $\tau=\tau'$
(Proposition~\ref{prop:basic}, Theorem~\ref{thm:affine}); symmetry is
Propositions~\ref{prop:inv} and~\ref{prop:groupoid}; the triangle inequality is
Theorem~\ref{thm:submult} with Proposition~\ref{prop:groupoid}, after taking logarithms.
\end{proof}

The construction is intrinsic: the metric axioms follow from the quasiconformal calculus alone.

\begin{theorem}[Main identification]\label{thm:main}
For all $\tau,\tau'\in\HH$,
\[
  \dT(\tau,\tau')=\tfrac12\,\dH(\tau,\tau'),\qquad\text{equivalently}\qquad
  K(\tau,\tau')=e^{\dH(\tau,\tau')}.
\]
\end{theorem}

\begin{proof}
Set $p=|\tau'-\bar\tau|$, $q=|\tau'-\tau|$, $y=\Imm\tau$, $y'=\Imm\tau'$, so $0\le q<p$ and
$p^2=q^2+4yy'$, and $K=(p+q)^2/(4yy')$. Then
\[
  \cosh(2\dT)=\frac{K+K^{-1}}{2}
  =\frac{(p+q)^2+(p-q)^2}{2(p+q)(p-q)}
  =\frac{p^2+q^2}{p^2-q^2}=1+\frac{q^2}{2yy'}=\cosh\dH(\tau,\tau'),
\]
using $4yy'=p^2-q^2=(p+q)(p-q)$. Since $\cosh$ is injective on $[0,\infty)$ and both arguments
are nonnegative, $2\dT=\dH$.
\end{proof}

\begin{remark}
The factor $\tfrac12$ is forced: rescaling would break $K=1\iff\tau=\tau'$. The Teichm\"uller
metric of the once-marked torus is thus a hyperbolic metric of curvature $-4$.
\end{remark}

\begin{theorem}[The stretch line]\label{thm:stretch}
Let $\sigma_t=ie^{2t}$. Then $\dT(\sigma_s,\sigma_t)=|t-s|$; for $r\le s\le t$ the triangle
inequality is an equality along $\sigma$; and $K(\sigma_s,\sigma_t)=e^{2|t-s|}$. In particular
the Teichm\"uller space of the torus has infinite diameter.
\end{theorem}

\begin{proof}
For equal real parts, $\dH(iy,iy')=|\log y-\log y'|$; with $y=e^{2s}$, $y'=e^{2t}$ this is
$2|t-s|$, halved by Theorem~\ref{thm:main}. Additivity is the triangle equality for an ordered
triple of reals, and $K=e^{\dH}$ gives the dilatation.
\end{proof}

\section{Mapping class group and moduli pseudometric}

Change of marking is the M\"obius action of
$g=\left(\begin{smallmatrix}a&b\\c&d\end{smallmatrix}\right)\in SL(2,\ZZ)$ on $\HH$.

\begin{theorem}
$SL(2,\ZZ)$ acts by isometries of $\dT$.
\end{theorem}

\begin{definition}
$\displaystyle \dM(\tau,\tau')=\inf_{g\in SL(2,\ZZ)}\dT(\tau,g\cdot\tau')$.
\end{definition}

\begin{theorem}\label{thm:pseudo}
$\dM$ is a symmetric $SL(2,\ZZ)$-invariant pseudometric with $\dM\le\dT$ and
$\dM(\tau,h\cdot\tau)=0$; it is not a metric on $\HH$ (e.g.\ $i$ and $i+1$).
\end{theorem}

\begin{proof}
Invariance on either side is a reindexing of the group; symmetry uses
$\dT(\tau,g\cdot\tau')=\dT(\tau',g^{-1}\cdot\tau)$ and $g\mapsto g^{-1}$. For the triangle
inequality, for all $g,h$,
\[
  \dM(\tau,\tau'')\le\dT(\tau,(gh)\cdot\tau'')\le\dT(\tau,g\cdot\tau')+\dT(\tau',h\cdot\tau''),
\]
and one takes infima over $h$ then $g$.
\end{proof}

\begin{theorem}[Two cone points]\label{thm:cone}
\begin{enumerate}
\item $S=\left(\begin{smallmatrix}0&-1\\1&0\end{smallmatrix}\right)$ fixes $i$ and $S\ne\pm1$;
the action is not free.
\item Every $g$ fixing $i$ satisfies $g^2=\pm1$: the stabilizer of $i$ has order $2$ in
$PSL(2,\ZZ)$.
\item $ST=\left(\begin{smallmatrix}0&-1\\1&1\end{smallmatrix}\right)$ fixes $\rho$, with
$(ST)^3=-1$ and $ST,(ST)^2\notin\{\pm1\}$: the stabilizer of $\rho$ has order $3$.
\item Hence $g\cdot\rho\ne i$ for all $g$: the two points lie in distinct orbits, and the moduli
space carries two orbifold singularities of cone angles $\pi$ and $2\pi/3$.
\end{enumerate}
\end{theorem}

\begin{proof}
(1) and (3) are computations ($S\cdot i=-1/i=i$; $\rho^2+\rho+1=0$ gives $-1/(\rho+1)=\rho$).
(2) $(ai+b)/(ci+d)=i$ forces $a=d$, $b=-c$, so $\det g=a^2+c^2=1$, whose only integral solutions
are $(\pm1,0),(0,\pm1)$, all squaring to $\pm1$. (4) If $g\cdot\rho=i$ then $gSTg^{-1}$ fixes
$i$, so $(ST)^2=\pm1$ by (2), contradicting (3) (its $(0,1)$ entry is $-1$).
\end{proof}

\begin{theorem}[The cusp]\label{thm:cusp}
For $T:\tau\mapsto\tau+1$ one has $\cosh\dH(\tau,T\cdot\tau)=1+\frac{1}{2(\Imm\tau)^2}$. Hence
the displacement is positive at every point, yet its infimum is $0$ and is not attained.
\end{theorem}

\section{Displacement, translation lengths, and the length spectrum}

\begin{theorem}[Displacement identity]\label{thm:displacement}
Let $g=\left(\begin{smallmatrix}a&b\\c&d\end{smallmatrix}\right)$ have determinant $1$ and let
$z=x+iy\in\HH$. Then
\[
  \cosh\dH(z,g\cdot z)=\frac{(a+d)^2-2}{2}
  +\frac{\bigl(c(x^2+y^2)-(a-d)x-b\bigr)^2}{2y^2}.
\]
\end{theorem}

\begin{proof}
Writing $P(z)=cz^2-(a-d)z-b$ and using $\Imm(g\cdot z)=y/|cz+d|^2$ one gets
$\cosh\dH(z,g\cdot z)=1+|P(z)|^2/(2y^2)$. The polynomial identity
\[
  |P(z)|^2-y^2\bigl((a+d)^2-4\bigr)=\bigl(c(x^2+y^2)-(a-d)x-b\bigr)^2
\]
holds modulo $ad-bc=1$ (the difference of the two sides is $-4y^2(ad-bc-1)$).
\end{proof}

\begin{corollary}[Trichotomy]
$\inf_z\dH(z,g\cdot z)$ is $0$ and attained if $|\tr g|<2$; $0$ and not attained if $|\tr g|=2$,
$g\ne\pm1$; positive and attained if $|\tr g|>2$, the minimum locus being the axis
$c(x^2+y^2)-(a-d)x-b=0$.
\end{corollary}

\begin{definition}
For $|\tr g|>2$ the \emph{stretch factor} is
$\lambda(g)=\bigl(|\tr g|+\sqrt{(\tr g)^2-4}\bigr)/2>1$, the larger eigenvalue; it satisfies
$\lambda+\lambda^{-1}=|\tr g|$.
\end{definition}

\begin{theorem}[Bers' formula in genus one]\label{thm:bers}
For $g\in SL(2,\ZZ)$ with $|\tr g|>2$,
\[
  \min_{\tau\in\HH}\dT(\tau,g\cdot\tau)=\log\lambda(g),
\]
the minimum being attained on the axis of $g$.
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:displacement} the minimum of $\cosh\dH(\cdot,g\cdot)$ is
$\bigl((\tr g)^2-2\bigr)/2$, so the hyperbolic translation length is
$\arcosh\frac{(\tr g)^2-2}{2}$. From $\lambda+\lambda^{-1}=|\tr g|$,
$\cosh(2\log\lambda)=\frac{\lambda^2+\lambda^{-2}}{2}=\frac{(\tr g)^2-2}{2}$, so that length is
$2\log\lambda$; halving gives the claim.
\end{proof}

\begin{example}
For Arnold's cat map $\left(\begin{smallmatrix}2&1\\1&1\end{smallmatrix}\right)$, $\tr=3$ and
$\lambda=\frac{3+\sqrt5}{2}=\varphi^2$, so the translation length is
$2\log\varphi\approx0.962424$.
\end{example}

\begin{theorem}[Spectral gap]
Every Anosov class satisfies $\lambda(g)\ge\frac{3+\sqrt5}{2}$, hence
$\dT(\tau,g\cdot\tau)\ge2\log\varphi$ for all $\tau$.
\end{theorem}

\begin{definition}
For an integer $n\ge3$ put $\ell(n)=\log\frac{n+\sqrt{n^2-4}}{2}=\arcosh(n/2)$, and let
$\mathcal{S}=\{\log\lambda(g):g\in SL(2,\ZZ),\ |\tr g|>2\}$.
\end{definition}

\begin{theorem}[Complete determination of the spectrum]\label{thm:spectrum}
\begin{enumerate}
\item Each $n\ge3$ is realized: $A_n=\left(\begin{smallmatrix}n&-1\\1&0\end{smallmatrix}\right)
\in SL(2,\ZZ)$ has trace $n$ and translation length $\ell(n)$.
\item $\mathcal{S}=\{\ell(n):n\in\ZZ,\ n\ge3\}$.
\item $\ell$ is strictly increasing, so $\mathcal S$ is order-isomorphic to $\ZZ\cap[3,\infty)$.
\item $\log\lambda(g)\le M$ implies $|\tr g|\le2e^M$; hence $\mathcal S\cap(-\infty,M]$ is finite.
\item $\mathcal S$ is unbounded.
\item $\min\mathcal S=\ell(3)=2\log\varphi$, realized by the cat map.
\end{enumerate}
\end{theorem}

\begin{proof}
(1) $\det A_n=1$, $\tr A_n=n>2$; apply Theorem~\ref{thm:bers}. (2) ``$\supseteq$'' is (1);
``$\subseteq$'' because $\lambda(g)$ depends on $g$ only through the integer $|\tr g|\ge3$.
(3) Both $n$ and $\sqrt{n^2-4}$ increase. (4) From $\lambda+\lambda^{-1}=|\tr g|$ and
$1<\lambda\le e^M$ we get $|\tr g|\le e^M+1\le2e^M$, confining $n$ to
$3\le n\le\lceil2e^M\rceil$. (5), (6) are immediate.
\end{proof}

\begin{corollary}
$\#\{\ell\in\mathcal S:\ell\le L\}=\lfloor2\cosh L\rfloor-2\sim e^L$.
\end{corollary}

\section{The systolic functional and Hermite's constant}

The torus $\CC/\Lambda_\tau$ has area $\Imm\tau$ and closed geodesics of lengths $|m+n\tau|$.

\begin{definition}
$Q_{m,n}(\tau)=\dfrac{|m+n\tau|^2}{\Imm\tau}$ for $(m,n)\ne(0,0)$, and
$\sys(\tau)=\min_{(m,n)\ne(0,0)}Q_{m,n}(\tau)$.
\end{definition}

\begin{theorem}
The minimum is attained and $\sys(\tau)>0$.
\end{theorem}

\begin{proof}
Each $Q_{m,n}(\tau)>0$; the value $Q_{1,0}=1/\Imm\tau$ bounds the infimum above, and by
properness of the positive definite form $|m+n\tau|^2$ on $\ZZ^2$ only finitely many indices
compete.
\end{proof}

\begin{theorem}[Equivariance and invariance]\label{thm:equivariance}
For $g=\left(\begin{smallmatrix}a&b\\c&d\end{smallmatrix}\right)\in SL(2,\ZZ)$,
$Q_{m,n}(g\cdot\tau)=Q_{m',n'}(\tau)$ with $(m',n')=(md+nb,\ mc+na)$, a substitution of
determinant $1$. Hence $\sys(g\cdot\tau)=\sys(\tau)$.
\end{theorem}

\begin{proof}
$|m+n\,g\cdot\tau|^2=|m(c\tau+d)+n(a\tau+b)|^2/|c\tau+d|^2$ and
$\Imm(g\cdot\tau)=\Imm\tau/|c\tau+d|^2$, so the factors cancel; the numerator is
$|(md+nb)+(mc+na)\tau|^2$. The substitution is invertible over $\ZZ$.
\end{proof}

\begin{theorem}[Hermite's constant]\label{thm:hermite}
$\sys(\tau)\le2/\sqrt3$ for all $\tau$, with equality at the hexagonal torus:
$\sys(\rho)=2/\sqrt3$ and $\sys(i)=1$. Hence $\gamma_2=2/\sqrt3$, extremal at $\rho$.
\end{theorem}

\begin{proof}
Move $\tau$ into $\mathcal{D}=\{|\Ree w|\le\tfrac12,\ |w|\ge1\}$, where $\Imm w\ge\sqrt3/2$, so
$Q_{1,0}(w)\le2/\sqrt3$, and transport back by Theorem~\ref{thm:equivariance}. For sharpness,
$|m+n\rho|^2=m^2-mn+n^2$ is a positive integer for $(m,n)\ne0$, hence $\ge1$, and
$\Imm\rho=\sqrt3/2$; similarly $|m+ni|^2=m^2+n^2\ge1$.
\end{proof}

\begin{proposition}[Systole on the fundamental domain]\label{prop:sysfd}
If $|\Ree w|\le\tfrac12$ and $|w|\ge1$ then $\sys(w)=1/\Imm w$.
\end{proposition}

\begin{proof}
$|m+nw|^2=m^2+2mn\Ree w+n^2|w|^2\ge m^2-|mn|+n^2\ge1$ for $(m,n)\ne0$, with equality achieved
by $(1,0)$.
\end{proof}

\begin{theorem}[Log-Lipschitz property]\label{thm:lip}
For every fixed $(m,n)$,
$\bigl|\log Q_{m,n}(z)-\log Q_{m,n}(w)\bigr|\le\dH(z,w)$; consequently
\[
  \bigl|\log\sys z-\log\sys w\bigr|\le\dH(z,w)=2\dT(z,w),\qquad
  \log\frac{\sys z}{\sys w}\le2\,\dM(z,w).
\]
\end{theorem}

\begin{proof}
With $u=m+nz$, $v=m+nw$ and $\zeta=u\bar v\,\overline{(z-w)}$ one has
$\Imm\zeta=\bigl(|u|^2\Imm w-|v|^2\Imm z\bigr)$ up to normalization, and the inequality
$\bigl(Q(z)/Q(w)+Q(w)/Q(z)\bigr)/2\le\cosh\dH(z,w)$ becomes exactly $(\Imm\zeta)^2\le|\zeta|^2$.
Apply $\arcosh$. For $\sys$, use the index realizing the minimum at one of the two points; for
the moduli statement, apply the estimate to $z$ and $g\cdot w$ and use
Theorem~\ref{thm:equivariance}.
\end{proof}

\begin{theorem}[Metric separation of the cone points]\label{thm:sep}
If every nonzero lattice vector of $z$ satisfies $Q\ge r$ while some nonzero lattice vector of
$w$ satisfies $Q\le s$ with $0<s\le r$, then $\dM(z,w)\ge\tfrac12\log(r/s)$. In particular
$\dM(\rho,i)\ge\tfrac12\log(2/\sqrt3)\approx0.0719>0$.
\end{theorem}

\begin{proof}
For each $g$ the short index vector of $w$ transports to one of $g\cdot w$ with the same value;
comparing with the lower bound at $z$ through Theorem~\ref{thm:lip} gives
$\dH(z,g\cdot w)\ge\log(r/s)$ uniformly in $g$.
\end{proof}

Note that no compactness, properness, or attainment is used.

\section{Proper discontinuity and the metric on moduli space}

\begin{theorem}[Proper discontinuity]\label{thm:proper}
For all $z,w\in\HH$ and $R\in\RR$ the set $\{g\in SL(2,\ZZ):\dH(z,g\cdot w)\le R\}$ is finite.
\end{theorem}

\begin{proof}
$|cw+d|^2=\Imm w/\Imm(g\cdot w)$ and $|aw+b|^2=|g\cdot w|^2|cw+d|^2$. A bound
$\dH(z,g\cdot w)\le R$ confines $g\cdot w$ to a compact subset of $\HH$, hence bounds
$\Imm(g\cdot w)$ below and $|g\cdot w|$ above, so both displayed quantities are bounded. A
positive definite integral binary form takes any bounded value only finitely often, and a matrix
is its two rows.
\end{proof}

\begin{corollary}
Every stabilizer is finite (orders $2$ and $3$ projectively at the cone points), and the
infimum defining $\dM$ is attained.
\end{corollary}

\begin{theorem}\label{thm:zero}
$\dM(z,w)=0$ if and only if $g\cdot w=z$ for some $g\in SL(2,\ZZ)$. Hence $\dM$ descends to a
genuine metric on $\HH/SL(2,\ZZ)$, and distinct points of the moduli space are at positive
distance.
\end{theorem}

\begin{proof}
Sufficiency is invariance. Conversely, attainment gives $g_0$ with $\dT(z,g_0\cdot w)=0$, so
$g_0\cdot w=z$ by Theorem~\ref{thm:metric}. Attainment is genuinely needed: an infimum of
positive numbers over an infinite set can vanish, as Theorem~\ref{thm:cusp} shows.
\end{proof}

\section{Cusp exhaustion and Mahler compactness}

\begin{theorem}\label{thm:distfd}
If $|\Ree w|\le\tfrac12$ and $|w|\ge1$ then $\dH(\rho,w)\le\log(5\Imm w)$.
\end{theorem}

\begin{proof}
With $w=x+iy$ and $y\ge\sqrt3/2$,
$\cosh\dH(\rho,w)=1+\frac{(x+\frac12)^2+(y-\frac{\sqrt3}{2})^2}{\sqrt3 y}\le\frac52 y$, and
$e^t\le2\cosh t$ converts this into the stated bound.
\end{proof}

\begin{theorem}[Exhaustion comparison]\label{thm:exhaust}
For every $\tau\in\HH$,
\[
  \tfrac12\log\frac{1}{\sys\tau}\ \le\ \dM(\rho,\tau)\ \le\ \tfrac12\log\frac{5}{\sys\tau},
  \qquad\text{i.e.}\qquad
  \Bigl|\dM(\rho,\tau)-\tfrac12\log\tfrac{1}{\sys\tau}\Bigr|\le\tfrac12\log5 .
\]
\end{theorem}

\begin{proof}
The lower bound is Theorem~\ref{thm:lip} with $z=\rho$ and $\sys\rho>1$. For the upper bound
move $\tau$ into $\mathcal{D}$ by $g$; then $\sys(g\cdot\tau)=1/\Imm(g\cdot\tau)$
(Proposition~\ref{prop:sysfd}) and Theorem~\ref{thm:distfd} gives
$\dM(\rho,\tau)\le\tfrac12\dH(\rho,g\cdot\tau)\le\tfrac12\log(5/\sys\tau)$.
\end{proof}

\begin{theorem}[Continuity]
$\log\sys$ is $1$-Lipschitz for $\dH$; in particular $\sys$ is continuous. (This is not formal:
$\sys$ is an infimum over the infinite index set $\ZZ^2\setminus\{0\}$.)
\end{theorem}

\begin{theorem}[Mahler compactness]\label{thm:mahler}
For every $\varepsilon>0$ the set
\[
  K_\varepsilon=\Bigl\{w:|\Ree w|\le\tfrac12,\ |w|\ge1,\ \sys w\ge\varepsilon\Bigr\}
  =\Bigl\{w:|\Ree w|\le\tfrac12,\ |w|\ge1,\ \Imm w\le1/\varepsilon\Bigr\}
\]
is compact, and every $\tau$ with $\sys\tau\ge\varepsilon$ has a translate in $K_\varepsilon$.
It is nonempty for $\varepsilon\le2/\sqrt3$, since it contains $\rho$.
\end{theorem}

\begin{corollary}
$\tau\mapsto\dM(\rho,\tau)$ is $\tfrac12$-Lipschitz, hence continuous; closed balls of the
moduli space are compact, so the moduli space of tori is a proper metric space, and $\sys$
attains a maximum on every compact set and on every moduli ball.
\end{corollary}

\section{Successive minima}

\begin{theorem}[Determinant inequality]\label{thm:det}
If $mq-np\ne0$ then $Q_{m,n}(\tau)\,Q_{p,q}(\tau)\ge1$.
\end{theorem}

\begin{proof}
With $u=m+n\tau$, $v=p+q\tau$, Lagrange's identity gives
$|u|^2|v|^2=(\Ree\bar uv)^2+(\Imm\bar uv)^2\ge(\Imm\bar uv)^2$, and
$\Imm(\bar uv)=(mq-np)\Imm\tau$. Hence $Q_{m,n}Q_{p,q}\ge(mq-np)^2\ge1$.
\end{proof}

\begin{theorem}[Collar lemma]\label{thm:collar}
If $(m,n)$ realizes the systole, then $Q_{p,q}(\tau)\ge1/\sys\tau$ for every $(p,q)$
independent of $(m,n)$. On the thin part $\sys\tau<1$ this is a genuine gap
$\sys\tau<1<1/\sys\tau$.
\end{theorem}

\begin{corollary}
If $\sys\tau<1$ the shortest lattice vector is unique up to sign: a thin flat torus has exactly
one shortest closed geodesic. The hypothesis is sharp --- the square torus has $\sys=1$ and four
shortest vectors.
\end{corollary}

\begin{definition}
$\sys_2(\tau)=\inf\{r:\{Q_{m,n}(\tau)\le r\}\text{ contains two independent index vectors}\}$.
\end{definition}

\begin{theorem}[Attainment and simultaneity]
The infimum is attained, and it is attained together with the systole: there are independent
$(m,n)$, $(p,q)$ with $Q_{m,n}=\sys\tau$ and $Q_{p,q}=\sys_2\tau$. Moreover
$\sys\tau\le\sys_2\tau$, and $\sys_2$ is $SL(2,\ZZ)$-invariant.
\end{theorem}

\begin{proof}
Fix a shortest vector $u_0$. If $(\alpha,\beta)$ is an independent pair, at least one of them is
independent of $u_0$, since $\det(u_0,\alpha)=\det(u_0,\beta)=0$ forces $\det(\alpha,\beta)=0$.
Hence $\sys_2$ is the minimum of $Q$ over vectors independent of $u_0$, attained by finiteness.
Invariance follows since the index substitution of Theorem~\ref{thm:equivariance} is bijective
and satisfies $\det(T_gu,T_gv)=\det(u,v)\det g=\det(u,v)$.
\end{proof}

\begin{theorem}[Minkowski's second theorem, invariant form]\label{thm:minkowski}
$1\le\sys(\tau)\,\sys_2(\tau)\le4/3$ for every $\tau\in\HH$. On the fundamental domain,
\[
  \sys(w)=\frac{1}{\Imm w},\qquad \sys_2(w)=\frac{|w|^2}{\Imm w},\qquad
  \sys(w)\sys_2(w)=\frac{|w|^2}{(\Imm w)^2}.
\]
\end{theorem}

\begin{proof}
The lower bound is Theorem~\ref{thm:det} applied to a simultaneously realizing pair. For the
upper bound reduce to $\mathcal{D}$, where the product equals $1+(\Ree w)^2/(\Imm w)^2\le
1+\frac{1/4}{3/4}=\frac43$, using $|\Ree w|\le\frac12$ and $\Imm w\ge\sqrt3/2$.
\end{proof}

\begin{theorem}[Extremal loci]\label{thm:loci}
$\sys(\tau)\sys_2(\tau)=4/3$ if and only if $\tau$ lies in the orbit of the hexagonal torus
$\rho$; and $\sys(\tau)\sys_2(\tau)=1$ if and only if some $g\cdot\tau$ is rectangular, i.e.\
has real part $0$ and imaginary part $\ge1$.
\end{theorem}

\begin{proof}
Reduce to $\mathcal{D}$, where the product is $(x^2+y^2)/y^2$ with $|x|\le\frac12$,
$x^2+y^2\ge1$. It equals $4/3$ iff $x^2=y^2/3$, which with the constraints forces
$(x,y)=(\pm\frac12,\frac{\sqrt3}{2})$, the two corners, a single point of moduli; it equals $1$
iff $x=0$. The converse computations at $\rho$ (both minima $2/\sqrt3$, product $4/3$) and at
$iY$ with $Y\ge1$ ($\sys=1/Y$, $\sys_2=Y$, product $1$) are immediate.
\end{proof}

\section{Algorithms}

The theory is completely effective.

\textbf{(A) Reduction.} Given $\tau$, alternately translate so that $|\Ree\tau|\le\frac12$ and
invert ($\tau\mapsto-1/\tau$) while $|\tau|<1$, accumulating the matrix. Each inversion strictly
increases $\Imm\tau$, and the imaginary parts of an orbit form a discrete set with a maximum, so
the process terminates.

\textbf{(B) Minima.} After reduction, Theorem~\ref{thm:minkowski} gives $\sys$ and $\sys_2$ in
closed form. Alternatively enumerate indices in the box $|n|\le1/\Imm\tau$ with $m$ in an
interval of length $2$ for each $n$.

\textbf{(C) Distances.} $\dT=\tfrac12\arcosh\bigl(1+|\tau-\tau'|^2/(2\Imm\tau\Imm\tau')\bigr)$,
cross-checked against $\tfrac12\log K$ with $K$ from Theorem~\ref{thm:affine}. For $\dM$,
minimize over a finite set of group elements; finiteness is Theorem~\ref{thm:proper} and
Theorem~\ref{thm:exhaust} supplies an a priori bracket.

\textbf{(D) Length spectrum.} By Theorem~\ref{thm:spectrum} the spectrum below $L$ is
$\{\arcosh(n/2):3\le n\le2\cosh L\}$, an exact enumeration of cost $O(e^L)$.

\section{Discussion and open problems}

Each genus-one statement above models a much harder general theorem: uniqueness of the marked
affine map models Teichm\"uller's existence and uniqueness theorem; $\dT=\tfrac12\dH$ models
Royden's identification of the Teichm\"uller and Kobayashi metrics; Theorem~\ref{thm:bers}
models Bers' formula for pseudo-Anosov translation lengths; Theorem~\ref{thm:hermite} models
systolic inequalities; Theorem~\ref{thm:exhaust} models the thick--thin decomposition; and
Theorem~\ref{thm:mahler} models Mumford's compactness criterion.

Open problems.
\begin{enumerate}
\item[(E1)] \emph{Rigidity from the dilatation axioms.} Can the calculus of Section 2 alone
force every isometry of the Teichm\"uller metric to come from a mapping class?
\item[(E2)] \emph{Higher rank.} The determinant inequality generalizes to
$\lambda_1\cdots\lambda_n\ge1$ for unimodular lattices; which part of Theorem~\ref{thm:loci}
survives in rank three, where the extremal lattice is face-centered cubic?
\item[(E3)] \emph{Exact moduli distances.} Is there a closed formula for $\dM(\rho,\tau)$ in
terms of $\sys\tau$ and $\sys_2\tau$, sharpening the additive constant $\tfrac12\log5$?
\item[(E4)] \emph{Counting with multiplicity.} Counting Anosov conjugacy classes of length
$\le L$ leads to class numbers of binary quadratic forms.
\item[(E5)] \emph{Beyond the linear model.} Extending Section 3 from linear maps to all
quasiconformal homeomorphisms requires the length--area argument; this is the natural
completion of the picture.
\end{enumerate}

The unifying thread is that each analytic quantity has been reduced to an exact algebraic
identity: submultiplicativity to multiplicativity of the Jacobian; $\dT=\tfrac12\dH$ to the
reflection identity; the trichotomy of isometries to a perfect square over $2y^2$; the collar
lemma to ``a nonzero integer has square at least one''; and Mahler compactness to properness of
a positive definite integral quadratic form.

